(5207946, 758304, 89723, '<td valign="top">Rock star! I think she may be related to my step brother. Awesome shot with the exception of the ugly dude in the reflection.</td>', 'Rock star! I think she may be related to my step brother. Awesome shot with the exception of the ugly dude in the reflection.', '2009-01-21 00:02:59.000000', NULL, 1),
(5207988, 758368, 15711, '<td valign="top">Cute.  What a beautiful eye color.</td>', 'Cute.  What a beautiful eye color.', '2009-01-21 00:16:28.000000', NULL, 1),
(5207989, 757225, 15711, '<td valign="top">Love her glasses.  A touch soft for my taste. :~)</td>', 'Love her glasses.  A touch soft for my taste. :~)', '2009-01-21 00:16:42.000000', NULL, 1),
(5207998, 757312, 15711, '<td valign="top">Oh that is just about too fabulous.  The socks. LOL  That dog is a great sport. My only nitpick is the vignette around him, like you did a layer and then erased it.</td>', 'Oh that is just about too fabulous.  The socks. LOL  That dog is a great sport. My only nitpick is the vignette around him, like you did a layer and then erased it.', '2009-01-21 00:19:02.000000', NULL, 1),
(5208002, 757935, 15711, '<td valign="top">Great expression. I like the DOF. I remember her from a comment I made earlier today. Nice.</td>', 'Great expression. I like the DOF. I remember her from a comment I made earlier today. Nice.', '2009-01-21 00:19:29.000000', NULL, 1),
(5208005, 758349, 15711, '<td valign="top">That''s kinda cool and arty. :~)</td>', 'That''s kinda cool and arty. :~)', '2009-01-21 00:20:31.000000', NULL, 1),
(5208022, 757949, 15711, '<td valign="top">Oh that is really good.  Maybe a touch soft in the lower left (to our view) on the face, but I love the light and the use of negative space. I might''ve broadened the DOF just a smidge. :~)</td>', 'Oh that is really good.  Maybe a touch soft in the lower left (to our view) on the face, but I love the light and the use of negative space. I might''ve broadened the DOF just a smidge. :~)', '2009-01-21 00:24:02.000000', NULL, 1),
(5208023, 758040, 15711, '<td valign="top">I like it.  Blur is great!! (but not while driving LOL)</td>', 'I like it.  Blur is great!! (but not while driving LOL)', '2009-01-21 00:24:30.000000', NULL, 1),
(5208031, 758299, 15711, '<td valign="top">HEE HEE. That''s great.</td>', 'HEE HEE. That''s great.', '2009-01-21 00:25:35.000000', NULL, 1),
