(5212528, 757830, 34192, '<td valign="top">No clue why, but I love this image. 9 BTW - excellently toned and DOF perfect for subject.</td>', 'No clue why, but I love this image. 9 BTW - excellently toned and DOF perfect for subject.', '2009-01-22 19:34:40.000000', NULL, 1),
(5212532, 758307, 34192, '<td valign="top">Excellent treatment for subject - works perfectly together.  If the toning were a little more antique, I could actually imagine this being taken in the 1800s. 9</td>', 'Excellent treatment for subject - works perfectly together.  If the toning were a little more antique, I could actually imagine this being taken in the 1800s. 9', '2009-01-22 19:35:46.000000', NULL, 1),
(5212735, 757312, 100495, '<td valign="top">Very funny.<br/> <br/>There''s a strange halo effect going on behind the dog, especially aroind the collar.</td>', 'Very funny. There''s a strange halo effect going on behind the dog, especially aroind the collar.', '2009-01-22 20:30:38.000000', NULL, 1),
(5212749, 758317, 100495, '<td valign="top">Nice DOF and a good selective desaturation.  She needs to look a lot angrier and scarier though to carry off the menace of that big gun.</td>', 'Nice DOF and a good selective desaturation.  She needs to look a lot angrier and scarier though to carry off the menace of that big gun.', '2009-01-22 20:35:07.000000', NULL, 1),
(5212763, 757102, 100495, '<td valign="top">As a ''glasses-providing-different-focus'' photo this stands out from the others.  The FP wording is really clear and you''ve generated a really engaging DOF.  Well done on achieving a good result from a relatively over-used concept.</td>', 'As a ''glasses-providing-different-focus'' photo this stands out from the others.  The FP wording is really clear and you''ve generated a really engaging DOF.  Well done on achieving a good result from a relatively over-used concept.', '2009-01-22 20:41:51.000000', NULL, 1),
(5212770, 757843, 100495, '<td valign="top">I think natural light would have helped by removing the bright spot in the dog''s eyes and the reflection on the glasses.  Beautiful detail on the nose though.</td>', 'I think natural light would have helped by removing the bright spot in the dog''s eyes and the reflection on the glasses.  Beautiful detail on the nose though.', '2009-01-22 20:44:15.000000', NULL, 1),
(5212779, 758322, 100495, '<td valign="top">Bizarre and engaging.<br/> <br/>I think there''s a bit too much dead space on the left though.</td>', 'Bizarre and engaging. I think there''s a bit too much dead space on the left though.', '2009-01-22 20:45:42.000000', NULL, 1),
(5212790, 758251, 100495, '<td valign="top">I think it''s a good concept but the background lets it down.  I like that the subject is in focus and frames by another lens. Possibly needs les of a crop on the right.</td>', 'I think it''s a good concept but the background lets it down.  I like that the subject is in focus and frames by another lens. Possibly needs les of a crop on the right.', '2009-01-22 20:49:48.000000', NULL, 1),
(5212795, 757965, 100495, '<td valign="top">Bigger would have helped.</td>', 'Bigger would have helped.', '2009-01-22 20:51:21.000000', NULL, 1),
(5212800, 757803, 100495, '<td valign="top">I like the POV and the execution, however I''m not a fan of the border.</td>', 'I like the POV and the execution, however I''m not a fan of the border.', '2009-01-22 20:52:25.000000', NULL, 1),
(5212841, 758252, 76598, '<td valign="top">The eyes are a little blue, like a lot blue</td>', 'The eyes are a little blue, like a lot blue', '2009-01-22 21:04:15.000000', NULL, 1),
(5212856, 758335, 76598, '<td valign="top">Use more pixels</td>', 'Use more pixels', '2009-01-22 21:09:00.000000', NULL, 1),
(5212880, 758352, 76598, '<td valign="top">Really an excellent picture, but the title is the only thing to do with glasses.  The subject photographed should be proud of this picture.</td>', 'Really an excellent picture, but the title is the only thing to do with glasses.  The subject photographed should be proud of this picture.', '2009-01-22 21:13:55.000000', NULL, 1),
