(5218443, 757187, 35947, '<td valign="top">Neat, abstract like.</td>', 'Neat, abstract like.', '2009-01-25 19:05:31.000000', NULL, 1),
(5218446, 758024, 35947, '<td valign="top">Nice use of select desat to highlight the eye &amp; glasses.   They seem to sit on her face weird though, unnatural.</td>', 'Nice use of select desat to highlight the eye & glasses.   They seem to sit on her face weird though, unnatural.', '2009-01-25 19:06:46.000000', NULL, 1),
