(5220156, 757918, 100495, '<td valign="top">Great idea.<br/> <br/>2 minor points though; 1) the red/white/blue strap is distracting because it adds other colours to a relatively simple image and 2) if the image were flipped to make the wording on the camera normal it would be easier on the eye.</td>', 'Great idea. 2 minor points though; 1) the red/white/blue strap is distracting because it adds other colours to a relatively simple image and 2) if the image were flipped to make the wording on the camera normal it would be easier on the eye.', '2009-01-26 12:28:12.000000', NULL, 1),
(5220169, 758352, 100495, '<td valign="top">Funny image.  I find people that can''t find their glasses usually have them on top of their heads.</td>', 'Funny image.  I find people that can''t find their glasses usually have them on top of their heads.', '2009-01-26 12:30:26.000000', NULL, 1),
(5220172, 758177, 100495, '<td valign="top">I don''t think the highlighted hair at the left third adds to the image.  I think dead space would be better.<br/> <br/>Nice image otherwise.</td>', 'I don''t think the highlighted hair at the left third adds to the image.  I think dead space would be better. Nice image otherwise.', '2009-01-26 12:32:37.000000', NULL, 1),
(5220218, 757583, 18655, '<td valign="top">Very cool! The lighting on and around the hands is perfect and gives the whole setting a nice touch. Upgraded from a 5 to a 7 on second pass.</td>', 'Very cool! The lighting on and around the hands is perfect and gives the whole setting a nice touch. Upgraded from a 5 to a 7 on second pass.', '2009-01-26 12:55:34.000000', NULL, 1),
(5220220, 758151, 18655, '<td valign="top">Very creative :)</td>', 'Very creative :)', '2009-01-26 12:55:51.000000', NULL, 1),
(5220221, 756228, 18655, '<td valign="top">Nice clean shot but not overly interesting. Good use of shallow DOF thought.</td>', 'Nice clean shot but not overly interesting. Good use of shallow DOF thought.', '2009-01-26 12:55:54.000000', NULL, 1),
(5220222, 758350, 18655, '<td valign="top">Colorful and sharp. Nothing I would have on my wall but fun to look at!</td>', 'Colorful and sharp. Nothing I would have on my wall but fun to look at!', '2009-01-26 12:55:56.000000', NULL, 1),
(5220223, 758343, 18655, '<td valign="top">I like the antique feel to the picture but the boring pen and pad takes away from it. Still over all a nice looking picture. Looks like you entered the challenge from a hotel room... haven''t we all done that at least once? :)</td>', 'I like the antique feel to the picture but the boring pen and pad takes away from it. Still over all a nice looking picture. Looks like you entered the challenge from a hotel room... haven''t we all done that at least once? :)', '2009-01-26 12:55:59.000000', NULL, 1),
(5220226, 757914, 18655, '<td valign="top">I''m not sure if I understand the purpose of this ''layout'' but it doesn''t really matter - it looks interesting regardless. Good collection of glasses.</td>', 'I''m not sure if I understand the purpose of this ''layout'' but it doesn''t really matter - it looks interesting regardless. Good collection of glasses.', '2009-01-26 12:57:31.000000', NULL, 1),
(5220228, 758325, 18655, '<td valign="top">Creative and looks good. Clarity is good but you have a couple of annoying spots. They look like sensor dust but it might be something else.</td>', 'Creative and looks good. Clarity is good but you have a couple of annoying spots. They look like sensor dust but it might be something else.', '2009-01-26 12:57:43.000000', NULL, 1),
(5220230, 758177, 36981, '<td valign="top">lovely portrait - i love the darker mood</td>', 'lovely portrait - i love the darker mood', '2009-01-26 12:58:13.000000', NULL, 1),
(5220236, 757365, 18655, '<td valign="top">Very well balanced and an interesting shot. neither the guy nor the lamp is in focus but it doesn''t matter. I like it the way it is and it gives it an ''artsy'' look. Upgraded from a 5 to a 7 on second pass.</td>', 'Very well balanced and an interesting shot. neither the guy nor the lamp is in focus but it doesn''t matter. I like it the way it is and it gives it an ''artsy'' look. Upgraded from a 5 to a 7 on second pass.', '2009-01-26 12:59:50.000000', NULL, 1),
(5220237, 758073, 36981, '<td valign="top">I guess I''m not a fan tchotchkes, so images of them really don''t do anything for me.  Sorry.</td>', 'I guess I''m not a fan tchotchkes, so images of them really don''t do anything for me.  Sorry.', '2009-01-26 13:00:18.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5220240, 758239, 36981, '<td valign="top">I''m afraid that the lighting, color &amp; blur of this image isn''t really doing anything for me.</td>', 'I''m afraid that the lighting, color & blur of this image isn''t really doing anything for me.', '2009-01-26 13:00:48.000000', NULL, 1),
(5220243, 758317, 18655, '<td valign="top">Nice angle and use of wide angle. Very sharp and interesting to look at. The selective saturation works well also. I changed this from a 5 to a 7 after I had time to view it closer.</td>', 'Nice angle and use of wide angle. Very sharp and interesting to look at. The selective saturation works well also. I changed this from a 5 to a 7 after I had time to view it closer.', '2009-01-26 13:01:40.000000', NULL, 1),
(5220248, 758221, 18655, '<td valign="top">Very sharp and I like the reflection</td>', 'Very sharp and I like the reflection', '2009-01-26 13:03:08.000000', NULL, 1),
(5220249, 757349, 36981, '<td valign="top">I think it''s tough to for a picture like this to stand out, especially in this type of challenge.  In yours, I''m having trouble finding the focal point, which distracts me.</td>', 'I think it''s tough to for a picture like this to stand out, especially in this type of challenge.  In yours, I''m having trouble finding the focal point, which distracts me.', '2009-01-26 13:03:12.000000', NULL, 1),
(5220250, 758153, 18655, '<td valign="top">Lovely eyes and a great shot. I like the composition and crop. You might have been going for a shallow depth of field to get the attention drawn to the eyes and glasses but wish you had included the mouth.<br/>All in all a great shot!</td>', 'Lovely eyes and a great shot. I like the composition and crop. You might have been going for a shallow depth of field to get the attention drawn to the eyes and glasses but wish you had included the mouth.All in all a great shot!', '2009-01-26 13:03:13.000000', NULL, 1),
(5220253, 757225, 36981, '<td valign="top">This is just a little too soft for my taste, although I like the lighting on the right side of the image.</td>', 'This is just a little too soft for my taste, although I like the lighting on the right side of the image.', '2009-01-26 13:03:48.000000', NULL, 1),
(5220259, 757951, 18655, '<td valign="top">The angle and focal length work wonders here! Very sharp and attractive image. Upgraded from a 5 to a 7 on pass #2.</td>', 'The angle and focal length work wonders here! Very sharp and attractive image. Upgraded from a 5 to a 7 on pass #2.', '2009-01-26 13:05:08.000000', NULL, 1),
(5220261, 757370, 36981, '<td valign="top">I usually enjoy lots of negative space, but I think that, for me, for an image like this to work there has to be something really worth looking at in the smaller space.  Unfortunately, the glasses hide what is probably a very cute dog, and the glasses just aren''t interesting enough to make me want to look at them for long.</td>', 'I usually enjoy lots of negative space, but I think that, for me, for an image like this to work there has to be something really worth looking at in the smaller space.  Unfortunately, the glasses hide what is probably a very cute dog, and the glasses just aren''t interesting enough to make me want to look at them for long.', '2009-01-26 13:05:42.000000', NULL, 1),
(5220268, 757914, 36981, '<td valign="top">I guess I''m not sure what to take from this.  It seems like someone simply arranged all the glasses they owned on a hamper lid &amp; tapestry and took a picture, which is very meaningful to me.</td>', 'I guess I''m not sure what to take from this.  It seems like someone simply arranged all the glasses they owned on a hamper lid & tapestry and took a picture, which is very meaningful to me.', '2009-01-26 13:08:33.000000', NULL, 1),
(5220271, 758237, 36981, '<td valign="top">I just don''t understand this one.  Nothing seems particularly in focus, the colors aren''t appealing to me, and there''s no context for the "river".</td>', 'I just don''t understand this one.  Nothing seems particularly in focus, the colors aren''t appealing to me, and there''s no context for the "river".', '2009-01-26 13:10:14.000000', NULL, 1),
(5220276, 758368, 36981, '<td valign="top">Cute picture of a cutie.  Her eyes seem a bit off to me though - a little soft &amp; so bright they actually look a little odd.</td>', 'Cute picture of a cutie.  Her eyes seem a bit off to me though - a little soft & so bright they actually look a little odd.', '2009-01-26 13:13:11.000000', NULL, 1),
(5220280, 758033, 36981, '<td valign="top">The eyes scare me!  Is that contact lenses or processing?</td>', 'The eyes scare me!  Is that contact lenses or processing?', '2009-01-26 13:13:59.000000', NULL, 1),
(5220283, 758312, 36981, '<td valign="top">I like this image, but wish that the reflection wasn''t there and that there was a little more contrast.</td>', 'I like this image, but wish that the reflection wasn''t there and that there was a little more contrast.', '2009-01-26 13:14:30.000000', NULL, 1),
(5220288, 758141, 36981, '<td valign="top">This doesn''t feel real to me, and I''m not sure why.  Perhaps overprocessing? (was it run through portrait professional or something?)  The skin seems to have no texture &amp; the eyes seem overly bright, even for a boy as cute as him!</td>', 'This doesn''t feel real to me, and I''m not sure why.  Perhaps overprocessing? (was it run through portrait professional or something?)  The skin seems to have no texture & the eyes seem overly bright, even for a boy as cute as him!', '2009-01-26 13:16:44.000000', NULL, 1),
(5220359, 757925, 18655, '<td valign="top">An awesome portrait! Clear, sharp, good lighting and not in any way overdone. Excellent! Upgraded from a 5 (what was I thinking!!) to an 8 on my second pass and after studying it closer.</td>', 'An awesome portrait! Clear, sharp, good lighting and not in any way overdone. Excellent! Upgraded from a 5 (what was I thinking!!) to an 8 on my second pass and after studying it closer.', '2009-01-26 13:55:11.000000', NULL, 1),
(5220364, 758366, 18655, '<td valign="top">Very sharp and well done! Creative with the wording. 7</td>', 'Very sharp and well done! Creative with the wording. 7', '2009-01-26 13:56:24.000000', NULL, 1),
(5220367, 757987, 18655, '<td valign="top">A fun picture but more of a snap shot with too harsh lighting for me.</td>', 'A fun picture but more of a snap shot with too harsh lighting for me.', '2009-01-26 13:57:04.000000', NULL, 1),
(5220372, 758299, 18655, '<td valign="top">Fun picture but the crop doesn''t sit well with me.</td>', 'Fun picture but the crop doesn''t sit well with me.', '2009-01-26 13:57:55.000000', NULL, 1),
(5220381, 757949, 18655, '<td valign="top">Very clear, sharp and not overdone over saturated. Upped from a 5 to a 7 on second pass and after viewing it closer.</td>', 'Very clear, sharp and not overdone over saturated. Upped from a 5 to a 7 on second pass and after viewing it closer.', '2009-01-26 14:01:24.000000', NULL, 1),
(5220908, 758352, 102426, '<td valign="top">the picture is required to have some glasses in it. this has none.</td>', 'the picture is required to have some glasses in it. this has none.', '2009-01-26 19:28:34.000000', NULL, 1),
(5221191, 758350, 88810, '<td valign="top">Interesting subject,one of my favourites. 10</td>', 'Interesting subject,one of my favourites. 10', '2009-01-26 22:13:05.000000', NULL, 1),
(5221221, 757576, 88810, '<td valign="top">A wonderful use of glasses! An apt title.  Score of 10.</td>', 'A wonderful use of glasses! An apt title.  Score of 10.', '2009-01-26 22:38:18.000000', NULL, 1),
(5221253, 757583, 101668, '<td valign="top">Great picture but I can''t see the connection with eyeware.</td>', 'Great picture but I can''t see the connection with eyeware.', '2009-01-26 23:03:52.000000', NULL, 1),
(5221255, 757102, 101668, '<td valign="top">Although not unique, this is a great picture.</td>', 'Although not unique, this is a great picture.', '2009-01-26 23:05:05.000000', NULL, 1),
